/// <summary>
/// designed from AVA
/// </summary>
class AVACalcSalesQuotationLineGrossFactor    extends AVACalcSalesQuotationLine
{
}

Method.Source:
/// <summary>
/// designed from AVA
/// </summary>
/// <param name = "_dataContract">_contract</param>
public void processOperation(AVACalcSalesQuotationLineGrossFactorContract     _dataContract)
{
    AVACalcSalesQuotationLineGrossFactorContract contract = _datacontract;
    QuotationId                            quotationId = contract.parmQuotationId();
    //Factor                                 factor      = contract.parmFactor();
    AVAFactor                                 factor      = contract.parmFactor();
    SalesPrice                             newSalesPrice;

    while select salesQuotationLine
        where salesQuotationLine.QuotationId == quotationId
    {
        newSalesPrice = salesQuotationLine.KCS_LPSalesPrice * factor;
        newSalesPrice = decRound(newSalesPrice, 2);

        if (newSalesPrice < salesQuotationLine.KCS_LimitPrice)
        {
            newSalesPrice = salesQuotationLine.KCS_LimitPrice;
        }


        if (newSalesPrice  > salesQuotationLine.AVABestPrice)
        {
            salesQuotationLine.SalesPrice = salesQuotationLine.AVABestPrice;
        }
        // Commented for PBI 10475 -FINTHI
        //else if (newSalesPrice < salesQuotationLine.KCS_LimitPrice)
        //{
        //    salesQuotationLine.SalesPrice = salesQuotationLine.KCS_LimitPrice;
        //}
        else
        {
            salesQuotationLine.SalesPrice = newSalesPrice;
        }

        this.updateQuotationLineFields();
        ttsbegin;
        salesQuotationLine.selectForUpdate(true);
        salesQuotationLine.doUpdate();
        ttscommit;
    }

    this.updateLVPostion(quotationId);

}
